template<class Solve>
void benchmark(const char *name,int round,const QFont &baseFont,Solve solve)
{
    QCache<QByteArray,qreal> cache(256);
    quint64 measurements=0;
    const QString text="AAAAAAAA";
    const double dpi=96.;
    double natural=0.;
    const auto invoke=[&](double available,double previous){
        QImage device(1,1,QImage::Format_ARGB32_Premultiplied);
        device.setDotsPerMeterX(qRound(dpi/.0254));
        device.setDotsPerMeterY(qRound(dpi/.0254));
        const auto advance=[&](const QFont &font){
            QByteArray key;QDataStream stream(&key,QIODevice::WriteOnly);
            stream<<font<<text<<dpi;
            if(const auto *cached=cache.object(key))return *cached;
            ++measurements;
            const qreal width=QFontMetricsF(font,&device).horizontalAdvance(text);
            cache.insert(key,new qreal(width));
            return width;
        };
        natural=advance(baseFont);
        const auto at=[&](double coordinate){
            auto font=baseFont;
            font.setVariableAxis(QFont::Tag("wdth"),float(coordinate));
            return advance(font);
        };
        return solve(natural,available,previous,at);
    };
    const double coldAxis=invoke(1.,100.);
    const auto coldMeasurements=measurements;
    double previous=coldAxis;
    std::vector<qint64> durations;durations.reserve(400);
    double checksum=0.;
    for(int i=0;i<400;++i){
        const int phase=i%100;
        const double available=natural*(.5+(phase<50?phase:100-phase)*.012);
        QElapsedTimer timer;timer.start();
        previous=invoke(available,previous);
        durations.push_back(timer.nsecsElapsed());
        if(!std::isfinite(previous)||previous<90.||previous>100.)std::abort();
        checksum+=previous;
    }
    std::sort(durations.begin(),durations.end());
    QJsonObject result{{"algorithm",QString::fromLatin1(name)},{"round",round},
        {"naturalWidth",natural},{"coldRealMeasurements",qint64(coldMeasurements)},
        {"coldAxis",coldAxis},{"warmResizeCalls",400},
        {"warmRealMeasurements",qint64(measurements-coldMeasurements)},
        {"cacheEntries",cache.size()},{"medianUs",durations[200]/1000.},
        {"p95Us",durations[380]/1000.},{"axisChecksum",checksum}};
    std::cout<<QJsonDocument(result).toJson(QJsonDocument::Compact).constData()<<'\n';
}

int main(int argc,char **argv)
{
    QGuiApplication app(argc,argv);
    if(argc!=2)return 2;
    const int id=QFontDatabase::addApplicationFont(QString::fromLocal8Bit(argv[1]));
    const auto families=QFontDatabase::applicationFontFamilies(id);
    if(id<0||families.isEmpty())return 3;
    QFont font(families.first());font.setPixelSize(24);font.setWeight(QFont::Medium);
    font.setHintingPreference(QFont::PreferFullHinting);font.setStyleStrategy(QFont::PreferAntialias);
    font.clearVariableAxes();font.setVariableAxis(QFont::Tag("wght"),500.f);
    font.setVariableAxis(QFont::Tag("wdth"),100.f);
    if(QFontInfo(font).variableAxes().size()!=2)return 4;
