        {"kernel",QSysInfo::kernelVersion()},{"architecture",QSysInfo::currentCpuArchitecture()},
        {"family",font.family()},{"pixelSize",24},{"weight",500},{"dpi",96},
        {"fixture",QString::fromLocal8Bit(argv[1])},
        {"scope","isolated solve + QImage device + QFont/text/DPI QCache; excludes FontManager metadata/profile dispatch and QML"},
        {"coldDefinition","application measurement cache empty; shared Qt font-engine cache primed"}};
    std::cout<<QJsonDocument(environment).toJson(QJsonDocument::Compact).constData()<<'\n';
