        if(QFontMetricsF(sample).horizontalAdvance("AAAAAAAA")<=0)return 5;
    }
    const auto old=[](double natural,double available,double previous,auto measure){
        return oldSolve(75.,100.,natural,available,previous,measure);
    };
    const auto current=[](double natural,double available,double previous,auto measure){
        return FontWidthFit::solve(75.,100.,125.,natural,available,previous,measure);
    };
    for(int round=1;round<=5;++round){
        if(round%2){benchmark("old-50d2a8e8-five-step",round,font,old);benchmark("current-ten-step",round,font,current);}
        else{benchmark("current-ten-step",round,font,current);benchmark("old-50d2a8e8-five-step",round,font,old);}
    }
}

